// First checkout
library.checkout("978-0134685991", "Alice");
console.log("After first checkout - Available:", library.available("978-0134685991"));

// Second checkout - should fail because member already has it
try {
    library.checkout("978-0134685991", "Alice");
    console.log("ERROR: Second checkout succeeded when it should have failed");
} catch (e) {
    console.log("SUCCESS: Second checkout failed as expected:", e.message);
}

// Third checkout - should fail because no copies available
